<template>
  <div class="page-shell"><header class="page-header"><div><el-tag>第 3 步 / 4</el-tag><h1>简历与岗位匹配</h1><p>{{ session.candidate.name }} · {{ session.jobProfile.name }}</p></div><el-button @click="router.push('/job-analysis')">上一步</el-button></header>
    <el-steps :active="2" finish-status="success" class="flow"><el-step title="简历分析"/><el-step title="岗位建模"/><el-step title="人岗匹配"/><el-step title="评估方案"/></el-steps>
    <div v-if="loading" class="loading"><el-icon class="is-loading" size="42"><Loading/></el-icon><h3>AI 正在对齐简历证据与岗位要求...</h3></div>
    <template v-else-if="match">
      <el-row :gutter="20"><el-col :xs="24" :lg="7"><el-card shadow="never" class="score-card"><el-progress type="dashboard" :percentage="match.score" :width="190" :stroke-width="14"/><h2>综合匹配度</h2><el-tag size="large" type="success">{{ match.recommendation }}</el-tag><p>基于简历证据与岗位五维模型综合计算</p></el-card></el-col><el-col :xs="24" :lg="17"><el-card shadow="never"><template #header><strong>能力匹配雷达图</strong></template><CompetencyRadar :competencies="store.competencyModel"/></el-card></el-col></el-row>
      <el-row :gutter="20" class="section"><el-col :xs="24" :lg="8"><el-card shadow="never" class="result-card"><template #header><strong>✅ 匹配优势</strong></template><ul><li v-for="item in match.strengths" :key="item">{{ item }}</li></ul></el-card></el-col><el-col :xs="24" :lg="8"><el-card shadow="never" class="result-card"><template #header><strong>⚠️ 风险与能力缺口</strong></template><el-alert v-for="item in match.risks" :key="item" :title="item" type="warning" :closable="false" class="alert"/><div class="tags"><el-tag v-for="item in match.gaps" :key="item" type="danger">{{ item }}</el-tag></div></el-card></el-col><el-col :xs="24" :lg="8"><el-card shadow="never" class="result-card"><template #header><strong>🔍 待面试验证项</strong></template><el-timeline><el-timeline-item v-for="item in match.verificationItems" :key="item" type="primary">{{ item }}</el-timeline-item></el-timeline></el-card></el-col></el-row>
      <div class="actions"><el-button type="primary" size="large" @click="next">生成个性化面试方案</el-button></div>
    </template>
  </div>
</template>
<script setup>
import { computed,onMounted,ref } from "vue";import { useRouter } from "vue-router";import { ElMessage } from "element-plus";import { Loading } from "@element-plus/icons-vue";import { analyzeJobMatch } from "@/api/job";import CompetencyRadar from "@/components/competency/CompetencyRadar.vue";import { useAssessmentStore } from "@/store/assessment";
const router=useRouter();const store=useAssessmentStore();const loading=ref(false);const session=computed(()=>store.session);const match=computed(()=>session.value.matchResult);
onMounted(async()=>{if(!session.value.resumeProfile.summary||!session.value.jobProfile.name){ElMessage.warning("请先完成简历与岗位分析");router.replace('/resume-analysis');return}if(!match.value){loading.value=true;const result=await analyzeJobMatch({resumeProfile:session.value.resumeProfile,jobProfile:session.value.jobProfile});store.setCompetencyModel(result.competencyModel);store.setMatchResult(result);loading.value=false;ElMessage.success("人岗匹配分析完成")}});const next=()=>{store.persist();router.push('/assessment-plan')};
</script>
